"""docich#4688: a stuck army must be allowed to recruit.

ch3 2026-11-19 month 11-x: defense_wait cycles 6, every castle one general,
interim_candidates {} even with allow_sole and 1501G unused, while
_defer_recruit_for_egg deferred recruitment every month for the egg check.
"""
from docich.hanjuku_speedrun.hanjuku.strategy import economy


def memory(gold=1501, reserve=450, cycles=6, recruit='check'):
    return {'gold': gold, 'defense_wait': {'cycles': cycles},
            'shop': {'key': '11-7', 'recruit': recruit, 'reserve': reserve,
                     'egg': 'skipped'}}


def test_a_stuck_army_recruits_when_the_egg_reserve_is_paid():
    mem = memory()
    economy._defer_recruit_for_egg(mem, mem['shop'])
    assert mem['shop']['recruit'] == 'check'
    assert any(r.get('decision') == 'recruit_promoted_for_stuck_army'
               for r in mem.get('_records') or [])


def test_an_ordinary_month_still_defers():
    mem = memory(cycles=0)
    economy._defer_recruit_for_egg(mem, mem['shop'])
    assert mem['shop']['recruit'] == 'deferred_egg'


def test_a_poor_month_still_defers():
    mem = memory(gold=470)   # reserve 450 + 50 is not covered
    economy._defer_recruit_for_egg(mem, mem['shop'])
    assert mem['shop']['recruit'] == 'deferred_egg'
